def main():
    df = pd.read_csv("golden_set/unlabeled.csv")
    assert len(df) == len(LABELS), f"{len(df)} rows vs {len(LABELS)} labels"
    for col in ["true_intent", "ideal_reply_direction", "escalate_reason"]:
        df[col] = df[col].astype(object)
    df["escalate"] = False
    for i, row in df.iterrows():
        intent, direction, escalate, reason = LABELS[i]
        df.at[i, "true_intent"] = intent
        df.at[i, "ideal_reply_direction"] = direction
        df.at[i, "escalate"] = escalate
        df.at[i, "escalate_reason"] = reason
    df.to_csv("golden_set/golden_set.csv", index=False)
    print(f"wrote golden_set/golden_set.csv, {len(df)} rows, {df['escalate'].sum()} escalations")

if __name__ == "__main__":
    main()
